Proceso MultiplicacionDeMatrices
    Dimension a[2, 2] Como Entero;
    Dimension b[2, 2] Como Entero;
    Dimension c[2, 2] Como Entero;
    Definir fila Como Entero;
    Definir columna Como Entero;
    Definir k Como Entero;
    Definir suma Como Entero;
    Para fila <- 0 Hasta 1 Con Paso 1 Hacer
        Para columna <- 0 Hasta 1 Con Paso 1 Hacer
            Leer a[fila, columna];
        FinPara
    FinPara
    Para fila <- 0 Hasta 1 Con Paso 1 Hacer
        Para columna <- 0 Hasta 1 Con Paso 1 Hacer
            Leer b[fila, columna];
        FinPara
    FinPara
    Para fila <- 0 Hasta 1 Con Paso 1 Hacer
        Para columna <- 0 Hasta 1 Con Paso 1 Hacer
            suma <- 0;
            Para k <- 0 Hasta 1 Con Paso 1 Hacer
                suma <- suma + a[fila, k] * b[k, columna];
            FinPara
            c[fila, columna] <- suma;
        FinPara
    FinPara
    Para fila <- 0 Hasta 1 Con Paso 1 Hacer
        Para columna <- 0 Hasta 1 Con Paso 1 Hacer
            Escribir c[fila, columna];
        FinPara
    FinPara
FinProceso
